use axum::{extract::{Path, Query, State}, http::{HeaderMap, Method, StatusCode}, response::{IntoResponse, Response}, routing::{get, post}, Json, Router};
use chrono::{Duration, Utc};
use futures::TryStreamExt;
use jsonwebtoken::{decode, encode, DecodingKey, EncodingKey, Header, Validation};
use mongodb::{bson::{doc, oid::ObjectId, DateTime, Document}, options::IndexOptions, Client, IndexModel};
use rand::Rng;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{collections::HashMap, env, sync::Arc};
use tokio::sync::RwLock;
use tower_http::{cors::{Any, CorsLayer}, trace::TraceLayer};

#[derive(Clone)] struct AppState { db: mongodb::Database, otps: Arc<RwLock<HashMap<String,(String,chrono::DateTime<Utc>)>>>, jwt: String }
#[derive(Debug,thiserror::Error)] enum ApiError { #[error("{0}")] Bad(String), #[error("Authentication required")] Unauthorized, #[error("{0}")] Db(#[from] mongodb::error::Error) }
impl IntoResponse for ApiError { fn into_response(self)->Response { let status=match self{Self::Bad(_)=>StatusCode::BAD_REQUEST,Self::Unauthorized=>StatusCode::UNAUTHORIZED,Self::Db(_)=>StatusCode::INTERNAL_SERVER_ERROR}; (status,Json(json!({"error":self.to_string()}))).into_response() } }
#[derive(Serialize,Deserialize)] struct Claims { sub:String,name:String,admin:bool,exp:usize }
#[derive(Deserialize)] struct OtpRequest { email:String }
#[derive(Deserialize)] struct VerifyRequest { email:String,code:String,display_name:String }
#[derive(Serialize,Deserialize,Clone)] struct Listing { #[serde(rename="_id",skip_serializing_if="Option::is_none")] id:Option<ObjectId>,kind:String,title:String,description:String,price:f64,area:String,owner_email:String,owner_name:String,status:String,meta:HashMap<String,String>,created_at:DateTime,expires_at:DateTime }
#[derive(Deserialize)] struct NewListing { kind:String,title:String,description:String,price:f64,area:String,#[serde(default)] meta:HashMap<String,String> }
#[derive(Deserialize)] struct ListingQuery { kind:Option<String>,search:Option<String> }
#[derive(Deserialize)] struct ReportRequest { listing_id:String,reason:String }

#[tokio::main] async fn main() -> Result<(),Box<dyn std::error::Error>> { dotenvy::dotenv().ok();tracing_subscriber::fmt().with_env_filter("campus_circle_api=debug,tower_http=debug").init();let uri=env::var("MONGODB_URI").unwrap_or_else(|_|"mongodb://localhost:27017".into());let client=Client::with_uri_str(uri).await?;let db=client.database(&env::var("MONGODB_DATABASE").unwrap_or_else(|_|"campus_circle".into()));create_indexes(&db).await?;let state=AppState{db,otps:Arc::new(RwLock::new(HashMap::new())),jwt:env::var("JWT_SECRET").unwrap_or_else(|_|"development-secret-change-me".into())};let cors=CorsLayer::new().allow_origin(Any).allow_headers(Any).allow_methods([Method::GET,Method::POST,Method::PATCH,Method::DELETE]);let app=Router::new().route("/health",get(||async{Json(json!({"status":"ok"}))})).route("/auth/request-otp",post(request_otp)).route("/auth/verify-otp",post(verify_otp)).route("/listings",get(listings).post(create_listing)).route("/listings/{id}/contact-request",post(contact_request)).route("/reports",post(report)).route("/dev/seed",post(seed)).layer(cors).layer(TraceLayer::new_for_http()).with_state(state);let addr=env::var("API_ADDR").unwrap_or_else(|_|"0.0.0.0:8080".into());let listener=tokio::net::TcpListener::bind(&addr).await?;tracing::info!("listening on {addr}");axum::serve(listener,app).await?;Ok(()) }
async fn create_indexes(db:&mongodb::Database)->mongodb::error::Result<()> { let unique=IndexOptions::builder().unique(true).build();db.collection::<Value>("users").create_index(IndexModel::builder().keys(doc!{"email":1}).options(unique).build()).await?;db.collection::<Listing>("listings").create_index(IndexModel::builder().keys(doc!{"kind":1,"created_at":-1}).build()).await?;Ok(()) }
fn valid_email(email:&str)->bool { email.len()>12&&email.to_ascii_lowercase().ends_with("@purdue.edu")&&email.split('@').next().is_some_and(|s|!s.is_empty()) }
async fn request_otp(State(s):State<AppState>,Json(input):Json<OtpRequest>)->Result<Json<Value>,ApiError>{let email=input.email.trim().to_ascii_lowercase();if !valid_email(&email){return Err(ApiError::Bad("Use a valid @purdue.edu email".into()))}let code=format!("{:06}",rand::rng().random_range(0..1_000_000));s.otps.write().await.insert(email,(code.clone(),Utc::now()+Duration::minutes(10)));Ok(Json(json!({"message":"Code sent","development_code":code})))}
async fn verify_otp(State(s):State<AppState>,Json(input):Json<VerifyRequest>)->Result<Json<Value>,ApiError>{let email=input.email.trim().to_ascii_lowercase();let ok=s.otps.read().await.get(&email).is_some_and(|(c,e)|c==&input.code&&e>&Utc::now());if !ok{return Err(ApiError::Bad("That code is invalid or expired".into()))}s.otps.write().await.remove(&email);let admin=email.starts_with("admin+");s.db.collection::<Value>("users").update_one(doc!{"email":&email},doc!{"$set":{"display_name":&input.display_name,"verified":true,"verified_at":DateTime::now()},"$setOnInsert":{"created_at":DateTime::now()}}).upsert(true).await?;let claims=Claims{sub:email.clone(),name:input.display_name.clone(),admin,exp:(Utc::now()+Duration::days(7)).timestamp() as usize};let token=encode(&Header::default(),&claims,&EncodingKey::from_secret(s.jwt.as_bytes())).map_err(|_|ApiError::Unauthorized)?;Ok(Json(json!({"token":token,"email":email,"display_name":input.display_name,"admin":admin})))}
fn auth(headers:&HeaderMap,s:&AppState)->Result<Claims,ApiError>{let raw=headers.get("authorization").and_then(|v|v.to_str().ok()).and_then(|v|v.strip_prefix("Bearer ")).ok_or(ApiError::Unauthorized)?;decode::<Claims>(raw,&DecodingKey::from_secret(s.jwt.as_bytes()),&Validation::default()).map(|v|v.claims).map_err(|_|ApiError::Unauthorized)}
fn public_listing(l:Listing)->Value{json!({"id":l.id.map(|v|v.to_hex()).unwrap_or_default(),"kind":l.kind,"title":l.title,"description":l.description,"price":l.price,"area":l.area,"owner_name":l.owner_name,"status":l.status,"meta":l.meta,"created_at":l.created_at.to_string()})}
async fn listings(State(s):State<AppState>,Query(q):Query<ListingQuery>)->Result<Json<Value>,ApiError>{let mut filter=doc!{"status":"active"};if let Some(k)=q.kind.filter(|v|!v.is_empty()){filter.insert("kind",k);}if let Some(search)=q.search.filter(|v|!v.is_empty()){filter.insert("$or",vec![doc!{"title":{"$regex":&search,"$options":"i"}},doc!{"description":{"$regex":&search,"$options":"i"}},doc!{"area":{"$regex":&search,"$options":"i"}}]);}let rows=s.db.collection::<Listing>("listings").find(filter).sort(doc!{"created_at":-1}).limit(100).await?.try_collect::<Vec<_>>().await?;Ok(Json(Value::Array(rows.into_iter().map(public_listing).collect())))}
async fn create_listing(State(s):State<AppState>,headers:HeaderMap,Json(input):Json<NewListing>)->Result<Json<Value>,ApiError>{let user=auth(&headers,&s)?;if !["housing","marketplace","ride"].contains(&input.kind.as_str())||input.title.len()<5||input.description.len()<20{return Err(ApiError::Bad("Add a clear title and at least 20 characters of detail".into()))}let mut listing=Listing{id:None,kind:input.kind,title:input.title,description:input.description,price:input.price,area:input.area,owner_email:user.sub,owner_name:user.name,status:"active".into(),meta:input.meta,created_at:DateTime::now(),expires_at:DateTime::from_millis((Utc::now()+Duration::days(30)).timestamp_millis())};let result=s.db.collection::<Listing>("listings").insert_one(&listing).await?;listing.id=result.inserted_id.as_object_id();Ok(Json(public_listing(listing)))}
async fn contact_request(State(s):State<AppState>,headers:HeaderMap,Path(id):Path<String>)->Result<Json<Value>,ApiError>{let user=auth(&headers,&s)?;let oid=ObjectId::parse_str(id).map_err(|_|ApiError::Bad("Invalid listing".into()))?;s.db.collection::<Document>("contact_requests").insert_one(doc!{"listing_id":oid,"requester_email":user.sub,"status":"pending","created_at":DateTime::now()}).await?;Ok(Json(json!({"message":"Contact request sent. The lister can approve it in-app."})))}
async fn report(State(s):State<AppState>,headers:HeaderMap,Json(input):Json<ReportRequest>)->Result<Json<Value>,ApiError>{let user=auth(&headers,&s)?;let oid=ObjectId::parse_str(input.listing_id).map_err(|_|ApiError::Bad("Invalid listing".into()))?;s.db.collection::<Document>("reports").insert_one(doc!{"listing_id":oid,"reporter_email":user.sub,"reason":input.reason,"status":"open","created_at":DateTime::now()}).await?;Ok(Json(json!({"message":"Report sent for review"})))}
async fn seed(State(s):State<AppState>)->Result<Json<Value>,ApiError>{let c=s.db.collection::<Listing>("listings");if c.count_documents(doc!{}).await?>0{return Ok(Json(json!({"inserted":0})))}let now=DateTime::now();let exp=DateTime::from_millis((Utc::now()+Duration::days(30)).timestamp_millis());let data=vec![("housing","Sunny room near Chauncey",720.0,"Chauncey Hill","Furnished room with a flexible May start.",[("dates","May–August"),("room","Private room")]),("marketplace","Trek commuter bike",180.0,"Central campus","Recently tuned, with lights and a U-lock.",[("condition","Good"),("category","Bikes")]),("ride","West Lafayette → Chicago",24.0,"PMU pickup","Leaving Friday after class with room for one carry-on.",[("departure","Fri · 4:30 PM"),("seats","2 seats")])];let docs=data.into_iter().map(|(kind,title,price,area,description,meta)|Listing{id:None,kind:kind.into(),title:title.into(),description:description.into(),price,area:area.into(),owner_email:"demo@purdue.edu".into(),owner_name:"Verified student".into(),status:"active".into(),meta:meta.into_iter().map(|(k,v)|(k.into(),v.into())).collect(),created_at:now,expires_at:exp}).collect::<Vec<_>>();let n=c.insert_many(docs).await?.inserted_ids.len();Ok(Json(json!({"inserted":n})))}
